using Autodesk.Revit.DB;
var doc = Document;
// Goal: create a Gross Building area plan on a level, enclose a region with area boundary lines,
// place an Area inside it and tag it, then read the computed area. Reads at top level; every write
// is in one WithTransaction block.

// 1. Level: the lowest existing level.
Level level = null;
foreach (Level l in new FilteredElementCollector(doc).OfClass(typeof(Level)))
  if (level == null || l.Elevation < level.Elevation) level = l;
if (level == null) throw new System.Exception("no level in document");

// 2. The area scheme. A Gross Building plan measures to the outside; pick the scheme whose
//    AreaScheme.IsGrossBuildingArea is true, falling back to the first scheme (e.g. "Rentable").
//    AreaScheme has no native collector class filter beyond OfClass(typeof(AreaScheme)).
AreaScheme scheme = null, firstScheme = null;
foreach (AreaScheme s in new FilteredElementCollector(doc).OfClass(typeof(AreaScheme))) {
  if (firstScheme == null) firstScheme = s;
  if (s.IsGrossBuildingArea) { scheme = s; break; }
}
bool usedFallbackScheme = scheme == null;
if (scheme == null) scheme = firstScheme;
if (scheme == null) throw new System.Exception("no AreaScheme in this document");

return Connector.WithTransaction(doc, () => {
  double z = level.Elevation;
  // 3. The area plan VIEW is bound to a scheme, not just a level: ViewPlan.CreateAreaPlan takes the
  //    areaSchemeId and the levelId (a plain floor plan cannot host areas). Name it so it is findable.
  var av = ViewPlan.CreateAreaPlan(doc, scheme.Id, level.Id);
  av.Name = level.Name + " - " + scheme.Name + " Area";

  // 4. Area boundary lines define the region and are independent of walls. They need a SketchPlane
  //    at the level elevation and the AREA VIEW (av) as the third argument -- NewAreaBoundaryLine
  //    draws into that specific area plan. Draw a CLOSED rectangle: an open loop leaves the area
  //    unenclosed and its Area reads 0.
  var sp = SketchPlane.Create(doc, Plane.CreateByNormalAndOrigin(XYZ.BasisZ, new XYZ(0, 0, z)));
  var pts = new[] { new XYZ(0, 0, z), new XYZ(40, 0, z), new XYZ(40, 30, z), new XYZ(0, 30, z) };
  for (int i = 0; i < 4; i++)
    doc.Create.NewAreaBoundaryLine(sp, Line.CreateBound(pts[i], pts[(i + 1) % 4]), av);
  // 5. Regenerate so the enclosed region is resolved before placing the Area.
  doc.Regenerate();

  // 6. Place the Area at a UV that lies INSIDE the enclosed region (a point outside yields a
  //    zero-area, unbounded Area). NewArea takes the area view and a UV in plan coordinates.
  var center = new UV(20, 15);
  var area = doc.Create.NewArea(av, center);
  area.Name = "Gross - " + level.Name;
  doc.Regenerate();

  // 7. Tag it. NewAreaTag takes the Area ELEMENT directly (ViewPlan, Area, UV) -- unlike NewRoomTag,
  //    which takes a LinkElementId. The tag must go in the area view av.
  var tag = doc.Create.NewAreaTag(av, area, center);
  doc.Regenerate();

  return new {
    viewId = av.Id.Value, viewName = av.Name, scheme = scheme.Name,
    isGrossScheme = scheme.IsGrossBuildingArea, usedFallbackScheme,
    areaId = area.Id.Value, areaSqFt = area.Area, enclosed = area.Area > 0,
    tagId = tag.Id.Value
  };
});
